"""Bundle the menu as one executor-ready file. No third-party packages needed."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def bundle() -> str:
    core = (ROOT / "src/core.luau").read_text(encoding="utf-8")
    menu = (ROOT / "src/menu.luau").read_text(encoding="utf-8")
    return (
        "-- Delta PC: independent, keyless UI. Backend: your current executor.\n"
        "-- Source: https://github.com/a65407112-boop/deltapcnovirus\n"
        "-- Generated by build.py; edit src/ instead.\n"
        "local Core = (function()\n" + core + "\nend)()\n"
        "local mount = (function()\n" + menu + "\nend)()\n"
        "return mount(Core)\n"
    )


if __name__ == "__main__":
    output = ROOT / "delta.lua"
    output.write_text(bundle(), encoding="utf-8")
    print(f"Built {output.name}: {output.stat().st_size:,} bytes")
